begin;
select plan(9);
set local app.auvo_sync_write='true';
create temporary table outbox_snapshot_vinculo as select count(*) total from pcm.auvo_sync_outbox;
select throws_ok($$select pcm.sso_snapshot_capacidade_autorizado(null,null,5)$$,'55000','esforco_capacidade_bloqueado','fontes permanecem fechadas');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
 values('17300000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s172-snapshot-vinculo@example.test',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values('17300000-0000-4000-8000-000000000001','superadmin','Snapshot vínculo',true);
insert into pcm.clientes(id,nome,ativo,created_by) values ('17300000-0000-4000-8000-000000000002','Cliente A',true,'17300000-0000-4000-8000-000000000001'),('17300000-0000-4000-8000-000000000003','Cliente B',true,'17300000-0000-4000-8000-000000000001');
insert into pcm.funcionarios(id,nome,ativo) values('17300000-0000-4000-8000-000000000004','Técnico',true);
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values('17300000-0000-4000-8000-000000000001','capacidade.gerir','17300000-0000-4000-8000-000000000002'),('17300000-0000-4000-8000-000000000001','plano.gerir','17300000-0000-4000-8000-000000000002');
insert into pcm.capacidade_disponibilidades(id,cliente_id,funcionario_id,semana_inicio,destinados_minutos,reservas_minutos,ausencias_minutos,created_by,updated_by) values ('17300000-0000-4000-8000-000000000005','17300000-0000-4000-8000-000000000002','17300000-0000-4000-8000-000000000004','2026-10-26',600,60,30,'17300000-0000-4000-8000-000000000001','17300000-0000-4000-8000-000000000001');
insert into pcm.capacidade_intervalos_declarados(id,disponibilidade_id,revisao_disponibilidade,tipo,inicio,fim,fuso,referencia,request_id,ator_id) values ('17300000-0000-4000-8000-000000000006','17300000-0000-4000-8000-000000000005',1,'reserva','2026-10-26 10:00Z','2026-10-26 11:00Z','UTC','origem','17300000-0000-4000-8000-000000000007','17300000-0000-4000-8000-000000000001');
update pcm.capacidade_esforco_declarado_gate set habilitado=true where id;
update pcm.capacidade_fontes_mediacao_gate set habilitado=true where id;
update pcm.capacidade_demanda_gate set habilitado=true where id;
update pcm.sso_fila_obrigacoes_preparadas_gate set habilitado=true where id;
set local request.jwt.claims='{"sub":"17300000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}';
select throws_ok($$select pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)$$,'55000','vinculo_intervalo_bloqueado','vínculos exigem gate próprio');
update pcm.capacidade_vinculo_intervalo_gate set habilitado=true where id;
select pcm.sso_declarar_vinculo_intervalo('17300000-0000-4000-8000-000000000008','17300000-0000-4000-8000-000000000002','17300000-0000-4000-8000-000000000005','17300000-0000-4000-8000-000000000006',1,0,true,'informado');
set local role authenticated;
select is(jsonb_array_length(pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)->'vinculosIntervalo'),1,'vínculo no snapshot');
select is(pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)->'vinculosIntervalo'->0->>'tipo','reserva','natureza preservada');
select is(pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)->'disponibilidades'->0->>'reservas_minutos','60','nenhum desconto adicional');
select throws_ok($$select pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000003','2026-10-26',5)$$,'42501','capacidade_nao_encontrada_ou_sem_acesso','outro Cliente negado');
reset role;
update pcm.capacidade_disponibilidades set revisao=2 where id='17300000-0000-4000-8000-000000000005';
set local role authenticated;
select is(jsonb_array_length(pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)->'vinculosIntervalo'),0,'vínculo anterior não é transposto');
select is(pcm.sso_snapshot_capacidade_autorizado('17300000-0000-4000-8000-000000000002','2026-10-26',5)->>'completude','desconhecida','cobertura continua desconhecida');
reset role;
select is((select count(*) from pcm.auvo_sync_outbox),(select total from outbox_snapshot_vinculo),'nenhuma fixture enfileirada ao Auvo');
select * from finish();
rollback;
